/**
 * Authentication service
 * Handles login, signup, logout and token management
 * Requirements 3.1, 3.2, 4.1, 13.2, 13.4, 13.5
 */

import { apiClient } from './api';

// Types
export interface User {
  id: string;
  email: string;
  displayName: string;
  avatarUrl?: string;
  emailVerified: boolean;
  createdAt: string;
}

export interface Workspace {
  id: string;
  name: string;
  slug: string;
  role: string;
}

export interface AuthTokens {
  accessToken: string;
  refreshToken: string;
  expiresAt: number;
}

export interface LoginCredentials {
  email: string;
  password: string;
}

export interface SignupData {
  email: string;
  password: string;
  displayName: string;
  workspaceName?: string;
}

export interface AuthResponse {
  user: User;
  tokens: {
    access_token: string;
    refresh_token: string;
    expires_in: number;
    token_type: string;
  };
  workspace: Workspace;
}

// Token storage keys
const ACCESS_TOKEN_KEY = 'rawdrive_access_token';
const REFRESH_TOKEN_KEY = 'rawdrive_refresh_token';
const EXPIRES_AT_KEY = 'rawdrive_expires_at';
const USER_KEY = 'rawdrive_user';
const WORKSPACE_KEY = 'rawdrive_workspace';

/**
 * Get stored tokens
 */
export function getStoredTokens(): AuthTokens | null {
  const accessToken = localStorage.getItem(ACCESS_TOKEN_KEY);
  const refreshToken = localStorage.getItem(REFRESH_TOKEN_KEY);
  const expiresAt = localStorage.getItem(EXPIRES_AT_KEY);

  if (!accessToken || !refreshToken) {
    return null;
  }

  return {
    accessToken,
    refreshToken,
    expiresAt: expiresAt ? parseInt(expiresAt, 10) : 0,
  };
}

/**
 * Store tokens
 */
export function setStoredTokens(tokens: AuthTokens): void {
  localStorage.setItem(ACCESS_TOKEN_KEY, tokens.accessToken);
  localStorage.setItem(REFRESH_TOKEN_KEY, tokens.refreshToken);
  localStorage.setItem(EXPIRES_AT_KEY, tokens.expiresAt.toString());
}

/**
 * Clear stored tokens
 */
export function clearStoredTokens(): void {
  localStorage.removeItem(ACCESS_TOKEN_KEY);
  localStorage.removeItem(REFRESH_TOKEN_KEY);
  localStorage.removeItem(EXPIRES_AT_KEY);
  localStorage.removeItem(USER_KEY);
  localStorage.removeItem(WORKSPACE_KEY);
}

/**
 * Get stored user
 */
export function getStoredUser(): User | null {
  const userJson = localStorage.getItem(USER_KEY);
  if (!userJson) return null;

  try {
    return JSON.parse(userJson);
  } catch {
    return null;
  }
}

/**
 * Store user
 */
export function setStoredUser(user: User): void {
  localStorage.setItem(USER_KEY, JSON.stringify(user));
}

/**
 * Get stored workspace
 */
export function getStoredWorkspace(): Workspace | null {
  const wsJson = localStorage.getItem(WORKSPACE_KEY);
  if (!wsJson) return null;

  try {
    return JSON.parse(wsJson);
  } catch {
    return null;
  }
}

/**
 * Store workspace
 */
export function setStoredWorkspace(workspace: Workspace): void {
  localStorage.setItem(WORKSPACE_KEY, JSON.stringify(workspace));
}

/**
 * Check if user is authenticated (has valid tokens)
 */
export function isAuthenticated(): boolean {
  const tokens = getStoredTokens();
  if (!tokens) return false;

  // Check if access token is expired (with 60s buffer)
  if (tokens.expiresAt && Date.now() > tokens.expiresAt - 60000) {
    // Token expired, but we have refresh token
    return !!tokens.refreshToken;
  }

  return true;
}

/**
 * Login with email and password
 */
export async function login(credentials: LoginCredentials): Promise<{
  success: boolean;
  error?: string;
  user?: User;
  workspace?: Workspace;
}> {
  const response = await apiClient.post<AuthResponse>('/api/v1/auth/login', credentials);

  if (response.error) {
    return {
      success: false,
      error: response.error.message || 'Login failed',
    };
  }

  if (response.data) {
    const { user, tokens, workspace } = response.data;

    // Store tokens
    setStoredTokens({
      accessToken: tokens.access_token,
      refreshToken: tokens.refresh_token,
      expiresAt: Date.now() + tokens.expires_in * 1000,
    });

    // Store user and workspace
    setStoredUser(user);
    setStoredWorkspace(workspace);

    return { success: true, user, workspace };
  }

  return { success: false, error: 'Unknown error' };
}

/**
 * Signup with email and password
 */
export async function signup(data: SignupData): Promise<{
  success: boolean;
  error?: string;
  user?: User;
  workspace?: Workspace;
}> {
  const response = await apiClient.post<AuthResponse>('/api/v1/auth/signup', {
    email: data.email,
    password: data.password,
    display_name: data.displayName,
    workspace_name: data.workspaceName,
  });

  if (response.error) {
    return {
      success: false,
      error: response.error.message || 'Signup failed',
    };
  }

  if (response.data) {
    const { user, tokens, workspace } = response.data;

    // Store tokens
    setStoredTokens({
      accessToken: tokens.access_token,
      refreshToken: tokens.refresh_token,
      expiresAt: Date.now() + tokens.expires_in * 1000,
    });

    // Store user and workspace
    setStoredUser(user);
    setStoredWorkspace(workspace);

    return { success: true, user, workspace };
  }

  return { success: false, error: 'Unknown error' };
}

/**
 * Logout
 */
export async function logout(): Promise<void> {
  try {
    await apiClient.post('/api/v1/auth/logout');
  } catch (error) {
    console.error('Logout API call failed:', error);
  } finally {
    // Always clear local tokens
    clearStoredTokens();
  }
}

/**
 * Get Google OAuth URL
 */
export function getGoogleOAuthUrl(redirectTo?: string): string {
  const baseUrl = import.meta.env.VITE_API_URL || 'http://localhost:8000';
  const redirect = redirectTo || window.location.origin + '/workspace';
  return `${baseUrl}/api/v1/auth/oauth/google/start?redirect_uri=${encodeURIComponent(redirect)}`;
}

/**
 * Get current user from API
 */
export async function getCurrentUser(): Promise<User | null> {
  const response = await apiClient.get<{ user: User }>('/api/v1/users/me');

  if (response.data?.user) {
    setStoredUser(response.data.user);
    return response.data.user;
  }

  return null;
}

/**
 * Verify email with token
 */
export async function verifyEmail(token: string): Promise<{
  success: boolean;
  error?: string;
}> {
  const response = await apiClient.post<{ message: string }>('/api/v1/auth/verify-email', {
    token,
  });

  if (response.error) {
    return { success: false, error: response.error.message };
  }

  return { success: true };
}

/**
 * Request password reset
 */
export async function requestPasswordReset(email: string): Promise<{
  success: boolean;
  error?: string;
}> {
  const response = await apiClient.post<{ message: string }>('/api/v1/auth/forgot-password', {
    email,
  });

  if (response.error) {
    return { success: false, error: response.error.message };
  }

  return { success: true };
}

/**
 * Reset password with token
 */
export async function resetPassword(
  token: string,
  newPassword: string
): Promise<{
  success: boolean;
  error?: string;
}> {
  const response = await apiClient.post<{ message: string }>('/api/v1/auth/reset-password', {
    token,
    new_password: newPassword,
  });

  if (response.error) {
    return { success: false, error: response.error.message };
  }

  return { success: true };
}
